type:
∀ {m i : ℕ} (P : Fin m → Prop) [inst : DecidablePred P],
  have S := fun (j : ℕ) => {e : Fin m | ↑e + 1 < j ∧ P e};
  (S (i + 1)).card = (S i).card ∨ (S (i + 1)).card = (S i).card + 1

∀ {k n L : ℕ} (cuts : RiffleUpperV2.Cuts k n (L + 1)) (D : ℕ) {g ξ : ℝ} {ω ω' : RiffleUpperV2.Sample cuts}
  ⦃e : Fin (n - 1)⦄ (p : Fin k) (t : Fin (RiffleUpperV2.Exploration.pileSize cuts p - 1)),
  ¬↑t < RiffleUpperV2.Exploration.pileSize cuts p → False

∀ {k n L : ℕ} (cuts : RiffleUpperV2.Cuts k n (L + 1)) (D : ℕ) {g ξ : ℝ} {ω ω' : RiffleUpperV2.Sample cuts}
  ⦃e : Fin (n - 1)⦄ (p : Fin k) (t : Fin (RiffleUpperV2.Exploration.pileSize cuts p - 1)),
  ¬↑t + 1 < RiffleUpperV2.Exploration.pileSize cuts p → False
